bool SimpleAtof(absl::string_view str, float* absl_nonnull out) {
  str = StripLeadingAsciiWhitespace(str);
  while (!str.empty() && ascii_isspace(static_cast<unsigned char>(str.back()))) {
    str.remove_suffix(1);
  }
  if (str.empty()) {
    // absl::from_chars doesn't accept empty strings.
    return false;
  }
  // std::from_chars doesn't accept an initial +, so if one is present, skip
  // it while rejecting a second sign.
  if (str[0] == '+') {
    str.remove_prefix(1);
    if (str.empty() || str[0] == '+' || str[0] == '-') {
      return false;
    }
  }

